31	import org.springframework.samples.petclinic.rest.controller.BindingErrorsResponse;
32	import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
33	import org.springframework.samples.petclinic.service.CityCapacityExceededException;
34	import org.springframework.samples.petclinic.service.DailyOwnerLimitExceededException;
35	import org.springframework.samples.petclinic.service.DuplicateOwnerException;
36	import org.springframework.security.access.AccessDeniedException;
37	import org.springframework.validation.BindingResult;
38	import org.springframework.validation.FieldError;
39	import org.springframework.web.bind.MethodArgumentNotValidException;
40	import org.springframework.web.bind.annotation.ControllerAdvice;
41	import org.springframework.web.bind.annotation.ExceptionHandler;
42	import org.springframework.web.bind.annotation.ResponseBody;
43	
44	/**
45	 * Global Exception handler for REST controllers.
46	 * <p>
47	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
48	 *
49	 * @author Vitaliy Fedoriv
50	 * @author Alexander Dudkin
51	 */
52	@ControllerAdvice
53	public class ExceptionControllerAdvice {
54	
55	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
56	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
57	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
58	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
59	    private static final String ERROR_DUPLICATE_OWNER = "An owner with the same identity (telephone, email and household) already exists";
60	    private static final String ERROR_CITY_CAPACITY = "The owner's city has already reached its maximum number of owners";
61	    private static final String ERROR_DAILY_OWNER_LIMIT = "The maximum number of owners for today has already been reached";
62	
63	    /**
64	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
65	     * class.
66	     *
67	     * @param e     Object referring to the thrown exception.
68	     * @param status HTTP response status.
69	     * @param url URL request.
70	     */
71	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
72	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
73	        problemDetail.setType(URI.create(url.toString()));
74	        problemDetail.setTitle(e.getClass().getSimpleName());
75	        problemDetail.setDetail(detail);
76	        problemDetail.setProperty("timestamp", Instant.now());
77	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
78	        return problemDetail;
79	    }
80	
81	    /**
82	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
83	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
84	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
85	     * would catch it and report an authorization failure as a 500.
86	     *
87	     * @param e The {@link AccessDeniedException} to propagate
88	     * @throws AccessDeniedException always
89	     */
90	    @ExceptionHandler(AccessDeniedException.class)
91	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
92	        throw e;
93	    }
94	
95	    /**
96	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
97	     *
98	     * @param e The {@link Exception} to be handled
99	     * @param request {@link HttpServletRequest} object referring to the current request.
100	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
101	     */
102	    @ExceptionHandler(Exception.class)
103	    @ResponseBody
104	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
105	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
106	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
107	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
108	        return ResponseEntity.status(status).body(detail);
109	    }
110	
111	    /**
112	     * Handles {@link DuplicateOwnerException} raised when creating an owner whose whole identity key
113	     * (normalized telephone, email and household identifier) is already used by another owner,
114	     * returning a 409 Conflict status.
115	     *
116	     * @param e The {@link DuplicateOwnerException} to be handled
117	     * @param request {@link HttpServletRequest} object referring to the current request.
118	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status
119	     */
120	    @ExceptionHandler(DuplicateOwnerException.class)
121	    @ResponseBody
122	    public ResponseEntity<ProblemDetail> handleDuplicateOwnerException(DuplicateOwnerException e, HttpServletRequest request) {
123	        logger.warn("Duplicate owner identity at {} {}: {}",
124	            request.getMethod(),
125	            request.getRequestURI(),
126	            e.getMessage());
127	        HttpStatus status = HttpStatus.CONFLICT;
128	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_OWNER);
129	        return ResponseEntity.status(status).body(detail);
130	    }
131	
132	    /**
133	     * Handles {@link CityCapacityExceededException} raised when creating an owner in a city that has already
134	     * reached its maximum number of owners, returning a 409 Conflict status.
135	     *
136	     * @param e The {@link CityCapacityExceededException} to be handled
137	     * @param request {@link HttpServletRequest} object referring to the current request.
138	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status
139	     */
140	    @ExceptionHandler(CityCapacityExceededException.class)
141	    @ResponseBody
142	    public ResponseEntity<ProblemDetail> handleCityCapacityExceededException(CityCapacityExceededException e, HttpServletRequest request) {
143	        logger.warn("City capacity exceeded at {} {}: {}",
144	            request.getMethod(),
145	            request.getRequestURI(),
146	            e.getMessage());
147	        HttpStatus status = HttpStatus.CONFLICT;
148	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_CITY_CAPACITY);
149	        return ResponseEntity.status(status).body(detail);
150	    }
151	
152	    /**
153	     * Handles {@link DailyOwnerLimitExceededException} raised when creating an owner on a day that has already
154	     * reached its maximum number of registrations, returning a 429 Too Many Requests status.
155	     *
156	     * @param e The {@link DailyOwnerLimitExceededException} to be handled
157	     * @param request {@link HttpServletRequest} object referring to the current request.
158	     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests status
159	     */
160	    @ExceptionHandler(DailyOwnerLimitExceededException.class)
161	    @ResponseBody
162	    public ResponseEntity<ProblemDetail> handleDailyOwnerLimitExceededException(DailyOwnerLimitExceededException e, HttpServletRequest request) {
163	        logger.warn("Daily owner limit exceeded at {} {}: {}",
164	            request.getMethod(),
165	            request.getRequestURI(),
166	            e.getMessage());
167	        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
168	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DAILY_OWNER_LIMIT);
169	        return ResponseEntity.status(status).body(detail);
170	    }
171	
172	    /**
173	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
174	     * method returns a 404 Not Found status if an entity does not exist.
175	     *
176	     * @param e The {@link DataIntegrityViolationException} to be handled
177	     * @param request {@link HttpServletRequest} object referring to the current request.
178	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
179	     */
180	    @ExceptionHandler(DataIntegrityViolationException.class)
181	    @ResponseBody
182	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
183	        logger.warn("Data integrity violation at {} {}: {}",
184	            request.getMethod(),
185	            request.getRequestURI(),
186	            e.getMessage());
187	        logger.debug("Data integrity violation stacktrace", e);
188	        HttpStatus status = HttpStatus.NOT_FOUND;
189	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
190	        return ResponseEntity.status(status).body(detail);
191	    }
192	
193	    /**
194	     * Handles exception thrown by Bean Validation on controller methods parameters
195	     *
196	     * @param e The {@link MethodArgumentNotValidException} to be handled
197	     * @param request {@link HttpServletRequest} object referring to the current request.
198	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
199	     */
200	    @ExceptionHandler(MethodArgumentNotValidException.class)
201	    @ResponseBody
202	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
203	        HttpStatus status = HttpStatus.BAD_REQUEST;
204	        BindingErrorsResponse errors = new BindingErrorsResponse();
205	        BindingResult bindingResult = e.getBindingResult();
206	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
207	        detail.setProperty("errors", bindingResult.getFieldErrors().stream()
208	            .map(FieldError::getField)
209	            .distinct()
210	            .toList());
211	        if (bindingResult.hasErrors()) {
212	            errors.addAllErrors(bindingResult);
213	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
214	                .map(fieldError -> {
215	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
216	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
217	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
218	                        fieldError.getField(),
219	                        defaultMessage,
220	                        rejectedValue);
221	                    return new ValidationMessageDto(message)
222	                        .putAdditionalProperty("field", fieldError.getField())
223	                        .putAdditionalProperty("rejectedValue", rejectedValue)
224	                        .putAdditionalProperty("defaultMessage", defaultMessage);
225	                })
226	                .toList();
227	            logger.debug("Validation error at {} {}: {}",
228	                request.getMethod(),
229	                request.getRequestURI(),
230	                bindingResult.getFieldErrors());
231	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
232	            return ResponseEntity.status(status).body(detail);
233	        }
234	        return ResponseEntity.status(status).body(detail);
235	    }
236	
237	}
