264	    public String createOwner(Owner owner, boolean sharesHousehold) throws DataAccessException {
265	        owner.setHouseholdId(HouseholdIdGenerator.generate(owner.getLastName(), owner.getPostcode()));
266	        rejectIdentityCollision(owner);
267	        List<Owner> householdMembers = findHouseholdMembers(owner);
268	        if (!householdMembers.isEmpty() && !sharesHousehold) {
269	            throw new HouseholdDuplicateException(owner.getHouseholdId());
270	        }
271	        long ownersInCity = ownerRepository.countByCity(owner.getCity());
272	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
273	            throw new CityCapacityExceededException(owner.getCity(), MAX_OWNERS_PER_CITY);
274	        }
275	        LocalDate effectiveDate = owner.getRegistrationDate() == null ? LocalDate.now() : owner.getRegistrationDate();
276	        owner.setRegistrationDate(BusinessDayAdjuster.toBusinessDay(effectiveDate));
277	        long ownersOnDate = ownerRepository.countByRegistrationDate(owner.getRegistrationDate());
278	        if (ownersOnDate >= MAX_OWNERS_PER_DAY) {
279	            throw new DailyOwnerLimitExceededException(owner.getRegistrationDate(), MAX_OWNERS_PER_DAY);
280	        }
281	        owner.setBulkSignupWarning(ownersOnDate > BULK_SIGNUP_WARNING_THRESHOLD);
282	        flagPossibleDuplicate(owner, householdMembers, sharesHousehold);
283	        owner.setNamesakeCount(countNamesakes(owner));
284	        owner.setHouseholdSize(householdMembers.size() + 1);
285	        owner.setCustomerCode(CustomerCodeGenerator.format(
286	            LocalityResolver.resolve(owner.getCity(), owner.getPostcode()),
287	            owner.getTelephone(), owner.getLastName()));
288	        ownerRepository.save(owner);
289	        ownerAuditLogger.ownerCreated(owner);
290	        return owner.getHouseholdId();
291	    }
