293	    /**
294	     * Reject creating an owner whose whole {@link OwnerIdentityKey identity key} already belongs to
295	     * another owner. Because the telephone is part of the key, only an existing owner sharing every
296	     * key component (normalized telephone, email and household identifier) is a duplicate.
297	     */
298	    private void rejectIdentityCollision(Owner owner) {
299	        String identityKey = OwnerIdentityKey.of(owner);
300	        boolean collides = ownerRepository.findByTelephone(owner.getTelephone()).stream()
301	            .anyMatch(existing -> identityKey.equals(OwnerIdentityKey.of(existing)));
302	        if (collides) {
303	            throw new DuplicateOwnerException(identityKey);
304	        }
305	    }
306	
307	    /**
308	     * Flag the new owner as a possible (soft) duplicate of an existing household member carrying a
309	     * different telephone. The new owner is still created; {@code possibleDuplicate} is set to
310	     * whether such a match exists and {@code possibleDuplicateOf} to the matching owner's id (the
311	     * lowest when several match), or {@code null} when there is no match.
312	     *
313	     * <p>An owner that explicitly declares {@code sharesHousehold} is a <em>declared</em> household
314	     * member rather than a suspected duplicate, so it is never flagged.
315	     */
316	    private void flagPossibleDuplicate(Owner owner, List<Owner> householdMembers, boolean sharesHousehold) {
317	        Owner match = sharesHousehold ? null : householdMembers.stream()
318	            .filter(existing -> !owner.getTelephone().equals(existing.getTelephone()))
319	            .min(Comparator.comparingInt(Owner::getId))
320	            .orElse(null);
321	        owner.setPossibleDuplicate(match != null);
322	        owner.setPossibleDuplicateOf(match == null ? null : match.getId());
323	    }
