331	    /**
332	     * Count the owners that already exist sharing this owner's first name and last name, compared
333	     * case-insensitively. Invoked before the new owner is persisted, so it never counts itself.
334	     */
335	    private int countNamesakes(Owner owner) {
336	        return (int) ownerRepository.findByLastNameIgnoreCase(owner.getLastName()).stream()
337	            .filter(existing -> owner.getFirstName().equalsIgnoreCase(existing.getFirstName()))
338	            .count();
339	    }
340	
341	    /**
342	     * Find the existing owners that already share this owner's household, i.e. that derive the same
343	     * computed {@code householdId} (the same last name and postcode). An owner without a postcode
344	     * has no household peers.
345	     */
346	    private List<Owner> findHouseholdMembers(Owner owner) {
347	        if (owner.getPostcode() == null) {
348	            return List.of();
349	        }
350	        String householdId = owner.getHouseholdId();
351	        return ownerRepository.findByLastNameIgnoreCase(owner.getLastName()).stream()
352	            .filter(existing -> householdId.equals(
353	                HouseholdIdGenerator.generate(existing.getLastName(), existing.getPostcode())))
354	            .toList();
355	    }
